    /** The capture fixture owns only the temporary Minecraft quality setting. */
    private static CloudStatus forcedCloudStatus() {
        return switch (CLOUD_SCENARIO) {
            case "bounded" -> CloudStatus.FANCY;
            case "fast" -> CloudStatus.FAST;
            default -> null;
        };
    }
