	private static boolean isItemFrameScenario() {
		return "item-frame".equals(MODEL_MESH_SCENARIO) || "item-frame-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame".equals(MODEL_MESH_SCENARIO) || "glow-item-frame-invisible".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-item".equals(MODEL_MESH_SCENARIO) || "item-frame-map".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-item-rotated".equals(MODEL_MESH_SCENARIO) || "item-frame-map-rotated".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-map-decorated".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-item-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item".equals(MODEL_MESH_SCENARIO) || "glow-item-frame-map".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item-rotated".equals(MODEL_MESH_SCENARIO) || "glow-item-frame-map-rotated".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-map-invisible".equals(MODEL_MESH_SCENARIO) || "glow-item-frame-map-invisible".equals(MODEL_MESH_SCENARIO);
	}

	private static boolean isItemFrameItemScenario() {
		return "item-frame-item".equals(MODEL_MESH_SCENARIO) || "item-frame-item-rotated".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-item-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item-rotated".equals(MODEL_MESH_SCENARIO);
	}

	private static boolean isInvisibleItemFrameScenario() {
		return "item-frame-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-invisible".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-item-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item-invisible".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-map-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-map-invisible".equals(MODEL_MESH_SCENARIO);
	}

	private static boolean isItemFrameMapScenario() {
		return "item-frame-map".equals(MODEL_MESH_SCENARIO) || "item-frame-map-rotated".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-map-decorated".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-map".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-map-rotated".equals(MODEL_MESH_SCENARIO)
			|| "item-frame-map-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-map-invisible".equals(MODEL_MESH_SCENARIO);
	}

	private static boolean isItemFrameDecoratedMapScenario() {
		return "item-frame-map-decorated".equals(MODEL_MESH_SCENARIO);
	}

	private static int expectedItemFrameRotation() {
		return MODEL_MESH_SCENARIO.endsWith("-rotated") ? 3 : 0;
	}

	private static boolean itemFrameFixtureItemMatches(ItemFrame frame) {
		if (isItemFrameMapScenario()) {
			return frame.getItem().is(Items.FILLED_MAP) && frame.getItem().get(DataComponents.MAP_ID) != null
				&& itemFrameDecorationMatches(frame);
		}
		return isItemFrameItemScenario() ? frame.getItem().is(Items.DIAMOND) : frame.getItem().isEmpty();
	}

	private static boolean itemFrameDecorationMatches(ItemFrame frame) {
		if (!isItemFrameDecoratedMapScenario()) return true;
		MapItemSavedData data = MapItem.getSavedData(frame.getItem(), frame.level());
		if (data == null) return false;
		for (MapDecoration decoration : data.getDecorations()) {
			if (decoration.getSpriteLocation().equals(ResourceLocation.withDefaultNamespace("red_x"))
				&& decoration.x() == 24 && decoration.y() == -16 && decoration.rot() == 5
				&& decoration.renderOnFrame()) return true;
		}
		return false;
	}

	private static ItemStack itemFrameFixtureItem(ServerLevel serverLevel, BlockPos framePos) {
		if (isItemFrameMapScenario()) {
			ItemStack map = MapItem.create(serverLevel, framePos.getX(), framePos.getZ(), (byte)0, false, false);
			MapItemSavedData data = MapItem.getSavedData(map, serverLevel);
			if (data == null) throw new IllegalStateException("framed-map fixture did not create saved map data");
			for (int y = 0; y < 128; y++) {
				for (int x = 0; x < 128; x++) data.colors[x + y * 128] = (byte)(((x / 16 + y / 16) & 1) == 0 ? 30 : 46);
			}
            data.setDirty();
            if (isItemFrameDecoratedMapScenario()) {
				map.update(DataComponents.MAP_DECORATIONS, MapDecorations.EMPTY, decorations -> decorations.withDecoration(
					"mattmc-audit-red-x",
					new MapDecorations.Entry(MapDecorationTypes.RED_X, data.centerX + 12.0, data.centerZ - 8.25, 112.5F)
				));
            }
			return map;
		}
		return isItemFrameItemScenario() ? new ItemStack(Items.DIAMOND) : ItemStack.EMPTY;
	}

	private static boolean isGlowItemFrameScenario() {
		return "glow-item-frame".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-map".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item-rotated".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-map-rotated".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-item-invisible".equals(MODEL_MESH_SCENARIO)
			|| "glow-item-frame-map-invisible".equals(MODEL_MESH_SCENARIO);
	}

	private static EntityType<?> expectedItemFrameType() {
		return isGlowItemFrameScenario() ? EntityType.GLOW_ITEM_FRAME : EntityType.ITEM_FRAME;
	}

	private static String itemFrameSemanticIdentity() {
		return isGlowItemFrameScenario() ? "minecraft:glow_item_frame" : "minecraft:item_frame";
	}

	/** Passive observation after vanilla queues the synthetic item-frame backing model. */
	public static void observeItemFrameBackingEmission(Object state) {
		if (!ENABLED || complete || failed || !isItemFrameScenario()
			|| !(state instanceof net.minecraft.client.renderer.entity.state.ItemFrameRenderState frameState)
			|| frameState.entityType != expectedItemFrameType() || frameState.isInvisible
			|| frameState.rotation != expectedItemFrameRotation()
			|| frameState.isGlowFrame != isGlowItemFrameScenario()
			|| (isItemFrameMapScenario() ? frameState.mapId == null : frameState.mapId != null)
			|| (!isItemFrameMapScenario() && (isItemFrameItemScenario() ? frameState.item.isEmpty() : !frameState.item.isEmpty()))) return;
		ClientLevel level = Minecraft.getInstance().level;
		Entity fixture = level == null ? null : level.getEntity(cowModelFixtureEntityId);
		if (fixture instanceof ItemFrame frame && !frame.isInvisible()
			&& itemFrameFixtureItemMatches(frame)
			&& frame.getType() == expectedItemFrameType()
			&& Math.abs(frameState.x - fixture.getX()) <= 0.0001
			&& Math.abs(frameState.y - fixture.getY()) <= 0.0001
			&& Math.abs(frameState.z - fixture.getZ()) <= 0.0001) {
			lastItemFrameBackingEmission = new FrozenModelEmission(renderedFrameIndex + 1, fixture.getId(),
				itemFrameSemanticIdentity(), itemFrameSemanticIdentity(), frameState.x, frameState.y, frameState.z);
			lastItemFrameBackingLightCoords = frameState.lightCoords;
		}
	}

	/** Passive observation after vanilla queues the real framed item's FIXED-display model. */
	public static void observeItemFrameItemEmission(Object state, int lightCoords, float contentOffset) {
		if (!ENABLED || complete || failed || !isItemFrameItemScenario()
			|| !(state instanceof net.minecraft.client.renderer.entity.state.ItemFrameRenderState frameState)
			|| frameState.entityType != expectedItemFrameType()
			|| frameState.isInvisible != isInvisibleItemFrameScenario()
			|| frameState.rotation != expectedItemFrameRotation()
			|| frameState.isGlowFrame != isGlowItemFrameScenario() || frameState.mapId != null || frameState.item.isEmpty()) return;
		ClientLevel level = Minecraft.getInstance().level;
		Entity fixture = level == null ? null : level.getEntity(cowModelFixtureEntityId);
		if (fixture instanceof ItemFrame frame && frame.isInvisible() == isInvisibleItemFrameScenario()
			&& frame.getType() == expectedItemFrameType()
			&& frame.getItem().is(Items.DIAMOND)
			&& Math.abs(frameState.x - fixture.getX()) <= 0.0001
			&& Math.abs(frameState.y - fixture.getY()) <= 0.0001
			&& Math.abs(frameState.z - fixture.getZ()) <= 0.0001) {
			lastItemFrameItemEmission = new FrozenModelEmission(renderedFrameIndex + 1, fixture.getId(),
				"minecraft:diamond", itemFrameSemanticIdentity(), frameState.x, frameState.y, frameState.z);
			lastItemFrameItemLightCoords = lightCoords;
			lastItemFrameItemContentOffset = contentOffset;
		}
	}

	/** Passive observation after vanilla submits the framed map through its ordinary map renderer. */
	public static void observeItemFrameMapEmission(Object state, int lightCoords, float contentOffset) {
		if (!ENABLED || complete || failed || !isItemFrameMapScenario()
			|| !(state instanceof net.minecraft.client.renderer.entity.state.ItemFrameRenderState frameState)
			|| frameState.entityType != expectedItemFrameType()
			|| frameState.isInvisible != isInvisibleItemFrameScenario()
			|| frameState.rotation != expectedItemFrameRotation()
			|| frameState.isGlowFrame != isGlowItemFrameScenario()
			|| frameState.mapId == null || frameState.mapRenderState.texture == null) return;
		ClientLevel level = Minecraft.getInstance().level;
		Entity fixture = level == null ? null : level.getEntity(cowModelFixtureEntityId);
		MapId fixtureMapId = fixture instanceof ItemFrame frame ? frame.getItem().get(DataComponents.MAP_ID) : null;
		if (fixture instanceof ItemFrame frame && frame.isInvisible() == isInvisibleItemFrameScenario()
			&& frame.getType() == expectedItemFrameType() && itemFrameFixtureItemMatches(frame)
			&& fixtureMapId != null && fixtureMapId.equals(frameState.mapId)
			&& frameState.mapRenderState.texture.toString().equals("minecraft:map/" + fixtureMapId.id())
			&& Math.abs(frameState.x - fixture.getX()) <= 0.0001
			&& Math.abs(frameState.y - fixture.getY()) <= 0.0001
			&& Math.abs(frameState.z - fixture.getZ()) <= 0.0001) {
			lastItemFrameMapEmission = new FrozenItemFrameMapEmission(renderedFrameIndex + 1, fixture.getId(),
				fixtureMapId.id(), frameState.mapRenderState.texture.toString(), lightCoords,
				frameState.isInvisible, contentOffset);
			if (isItemFrameDecoratedMapScenario()) {
				for (var decoration : frameState.mapRenderState.decorations) {
					if (decoration.atlasSprite != null
						&& decoration.atlasSprite.contents().name().equals(ResourceLocation.withDefaultNamespace("red_x"))
						&& decoration.x == 24 && decoration.y == -16 && decoration.rot == 5 && decoration.renderOnFrame) {
						lastItemFrameMapDecorationEmission = new FrozenItemFrameMapDecorationEmission(
							renderedFrameIndex + 1, fixture.getId(), fixtureMapId.id(), "minecraft:red_x",
							decoration.x, decoration.y, decoration.rot, decoration.atlasSprite.atlasLocation().toString(), lightCoords);
					}
				}
			}
		}
	}

	private record FrozenItemFrameMapEmission(
		long frameIndex, int entityId, int mapId, String textureIdentity, int lightCoords,
		boolean invisibleFrame, float contentOffset
	) {
		private String json() {
			return "{\"stage\":\"map-render-returned\",\"frameIndex\":" + frameIndex
				+ ",\"fixtureEntityId\":" + entityId + ",\"mapId\":" + mapId
				+ ",\"textureIdentity\":\"" + escape(textureIdentity) + "\",\"lightCoords\":" + lightCoords
				+ ",\"invisibleFrame\":" + invisibleFrame + ",\"contentOffset\":" + contentOffset + "}";
		}
	}

	private record FrozenItemFrameMapDecorationEmission(
		long frameIndex, int entityId, int mapId, String decorationIdentity,
		byte x, byte y, byte rotation, String atlasIdentity, int lightCoords
	) {
		private String json() {
			return "{\"stage\":\"map-render-returned\",\"frameIndex\":" + frameIndex
				+ ",\"fixtureEntityId\":" + entityId + ",\"mapId\":" + mapId
				+ ",\"decorationIdentity\":\"" + escape(decorationIdentity) + "\",\"x\":" + x + ",\"y\":" + y
				+ ",\"rotation\":" + rotation + ",\"atlasIdentity\":\"" + escape(atlasIdentity)
				+ "\",\"lightCoords\":" + lightCoords + "}";
		}
	}

    /** Passive receipt after the ordinary Frozen enchanting-table model submission. */
