    /** Passive receipt after Frozen submits both the oak board and its text. */
    public static void observeOakSignEmission(
        net.minecraft.client.renderer.blockentity.state.SignRenderState state,
        net.minecraft.world.level.block.state.properties.WoodType woodType
    ) {
        if (!ENABLED || complete || failed || !isOakSignScenario()
            || oakSignFixturePosition == null || woodType != net.minecraft.world.level.block.state.properties.WoodType.OAK) return;
        ClientLevel level = Minecraft.getInstance().level;
        if (level == null || !(level.getBlockEntity(oakSignFixturePosition)
            instanceof net.minecraft.world.level.block.entity.SignBlockEntity sign)) return;
        String line0 = sign.getFrontText().getMessage(0, false).getString();
        String line1 = sign.getFrontText().getMessage(1, false).getString();
        if (!"Rust Vulkan".equals(line0) || !"Frozen parity".equals(line1)) return;
        String backLine0 = sign.getBackText().getMessage(0, false).getString();
        String backLine1 = sign.getBackText().getMessage(1, false).getString();
        boolean glowingBack = sign.getBackText().hasGlowingText();
        String backColor = sign.getBackText().getColor().getName();
        if (isGlowingBackOakSignScenario()
            && (!"Back face".equals(backLine0) || !"Glow parity".equals(backLine1)
                || !glowingBack || !"yellow".equals(backColor))) return;
		int destroyStage = state.breakProgress == null ? -1 : state.breakProgress.progress();
		if (isBreakingOakSignScenario() && destroyStage != MODEL_MESH_DESTROY_STAGE) return;
        lastOakSignEmission = new FrozenOakSignEmission(
            renderedFrameIndex + 1, oakSignFixturePosition, "minecraft:entity/signs/oak",
            state.lightCoords, line0, line1, backLine0, backLine1, glowingBack, backColor, destroyStage
        );
    }

