                + ",\"frontLines\":[\"" + escape(line0) + "\",\"" + escape(line1) + "\"]"
                + ",\"backLines\":[\"" + escape(backLine0) + "\",\"" + escape(backLine1) + "\"]"
                + ",\"glowingBack\":" + glowingBack + ",\"backColor\":\"" + escape(backColor)
				+ "\",\"destroyStage\":" + destroyStage + "}";
