    /** Passive receipt after Frozen submits the oak hanging-sign board and both text faces. */
    public static void observeHangingSignEmission(
        net.minecraft.client.renderer.blockentity.state.SignRenderState state,
        net.minecraft.world.level.block.state.properties.WoodType woodType
    ) {
        if (!ENABLED || complete || failed || !isOakHangingSignScenario()
            || oakHangingSignFixturePosition == null
            || woodType != net.minecraft.world.level.block.state.properties.WoodType.OAK) return;
        ClientLevel level = Minecraft.getInstance().level;
        if (level == null) return;
        BlockState blockState = level.getBlockState(oakHangingSignFixturePosition);
        boolean exactAttachment = isWallOakHangingSignScenario()
            ? blockState.is(Blocks.OAK_WALL_HANGING_SIGN)
                && blockState.getValue(net.minecraft.world.level.block.WallHangingSignBlock.FACING) == Direction.NORTH
                && level.getBlockState(oakHangingSignFixturePosition.east()).is(Blocks.STONE)
            : blockState.is(Blocks.OAK_HANGING_SIGN)
                && blockState.getValue(net.minecraft.world.level.block.CeilingHangingSignBlock.ROTATION) == 8
                && blockState.getValue(net.minecraft.world.level.block.CeilingHangingSignBlock.ATTACHED)
                    == isAttachedOakHangingSignScenario()
                && level.getBlockState(oakHangingSignFixturePosition.above()).is(Blocks.STONE);
        if (!exactAttachment || !(level.getBlockEntity(oakHangingSignFixturePosition)
            instanceof net.minecraft.world.level.block.entity.HangingSignBlockEntity sign)) return;
        String line0 = sign.getFrontText().getMessage(0, false).getString();
        String line1 = sign.getFrontText().getMessage(1, false).getString();
        if (!"Rust Vulkan".equals(line0) || !"Frozen parity".equals(line1)) return;
        lastOakHangingSignEmission = new FrozenOakHangingSignEmission(
            renderedFrameIndex + 1, oakHangingSignFixturePosition, state.lightCoords, line0, line1,
            isAttachedOakHangingSignScenario(), isWallOakHangingSignScenario());
    }

