    public static void observeShelfItemEmission(
        net.minecraft.client.renderer.blockentity.state.ShelfRenderState state
    ) {
        if (!ENABLED || complete || failed || !"oak-shelf".equals(MODEL_MESH_SCENARIO)
            || shelfItemFixturePosition == null) return;
        ClientLevel level = Minecraft.getInstance().level;
        if (level == null || !level.getBlockState(shelfItemFixturePosition).is(Blocks.OAK_SHELF)
            || level.getBlockState(shelfItemFixturePosition).getValue(net.minecraft.world.level.block.ShelfBlock.FACING) != Direction.SOUTH
            || !(level.getBlockEntity(shelfItemFixturePosition)
                instanceof net.minecraft.world.level.block.entity.ShelfBlockEntity shelf)
            || !shelf.getItems().get(1).is(Items.BEEF) || shelf.getAlignItemsToBottom()) return;
        int submittedItems = 0;
        int submittedSlot = -1;
        for (int i = 0; i < state.items.length; i++) {
            if (state.items[i] != null && !state.items[i].isEmpty()) {
                submittedItems++;
                submittedSlot = i;
            }
        }
        if (submittedItems != 1 || submittedSlot != 1 || state.alignToBottom) return;
        lastShelfItemEmission = new FrozenShelfItemEmission(
            renderedFrameIndex + 1, shelfItemFixturePosition, state.lightCoords, submittedSlot);
    }

