        ClientLevel level = Minecraft.getInstance().level;
        if (level == null || !state.blockPos.equals(expected) || !level.getBlockState(expected).is(Blocks.RED_BED)
            || level.getBlockState(expected).getValue(net.minecraft.world.level.block.BedBlock.FACING) != Direction.SOUTH
            || level.getBlockState(expected).getValue(net.minecraft.world.level.block.BedBlock.PART)
                != (state.isHead ? net.minecraft.world.level.block.state.properties.BedPart.HEAD
                    : net.minecraft.world.level.block.state.properties.BedPart.FOOT)
            || !(level.getBlockEntity(expected) instanceof net.minecraft.world.level.block.entity.BedBlockEntity)) return;
        FrozenBedEmission emission = new FrozenBedEmission(
            renderedFrameIndex + 1, expected, state.lightCoords, state.isHead);
