    /** Passive receipt after an ordinary Frozen single- or double-chest model submission returns. */
    public static void observeChestEmission(
        net.minecraft.client.renderer.blockentity.state.ChestRenderState state
    ) {
        boolean doubleChest = "chest-double".equals(MODEL_MESH_SCENARIO);
        boolean trapped = "chest-trapped".equals(MODEL_MESH_SCENARIO);
        boolean ender = "chest-ender".equals(MODEL_MESH_SCENARIO);
        if (!ENABLED || complete || failed
            || !("chest".equals(MODEL_MESH_SCENARIO) || doubleChest || trapped || ender) || chestFixturePosition == null
            || state.material != (ender
                ? net.minecraft.client.renderer.blockentity.state.ChestRenderState.ChestMaterialType.ENDER_CHEST
                : trapped ? net.minecraft.client.renderer.blockentity.state.ChestRenderState.ChestMaterialType.TRAPPED
                    : net.minecraft.client.renderer.blockentity.state.ChestRenderState.ChestMaterialType.REGULAR)
            || state.angle != Direction.SOUTH.toYRot() || state.open != 0.0F) return;
        var expectedType = doubleChest
            ? (state.blockPos.equals(chestFixturePosition)
                ? net.minecraft.world.level.block.state.properties.ChestType.RIGHT
                : state.blockPos.equals(chestFixturePosition.relative(Direction.EAST))
                    ? net.minecraft.world.level.block.state.properties.ChestType.LEFT : null)
            : state.blockPos.equals(chestFixturePosition)
                ? net.minecraft.world.level.block.state.properties.ChestType.SINGLE : null;
        if (expectedType == null || state.type != expectedType) return;
        ClientLevel level = Minecraft.getInstance().level;
        if (level == null || !level.getBlockState(state.blockPos)
                .is(ender ? Blocks.ENDER_CHEST : trapped ? Blocks.TRAPPED_CHEST : Blocks.CHEST)
            || level.getBlockState(state.blockPos).getValue(net.minecraft.world.level.block.ChestBlock.FACING) != Direction.SOUTH
            || !ender && level.getBlockState(state.blockPos).getValue(net.minecraft.world.level.block.ChestBlock.TYPE) != expectedType
            || !(level.getBlockEntity(state.blockPos)
                instanceof net.minecraft.world.level.block.entity.LidBlockEntity)
            || trapped && !(level.getBlockEntity(state.blockPos)
                instanceof net.minecraft.world.level.block.entity.TrappedChestBlockEntity)
            || ender && !(level.getBlockEntity(state.blockPos)
                instanceof net.minecraft.world.level.block.entity.EnderChestBlockEntity)) return;
        FrozenChestEmission emission = new FrozenChestEmission(
            renderedFrameIndex + 1, state.blockPos, state.lightCoords, state.open, expectedType.getSerializedName(),
            ender ? "minecraft:ender_chest" : trapped ? "minecraft:trapped_chest" : "minecraft:chest",
            ender ? "minecraft:entity/chest/ender" : trapped ? "minecraft:entity/chest/trapped" : "minecraft:entity/chest/normal"
                + (expectedType == net.minecraft.world.level.block.state.properties.ChestType.SINGLE
                    ? "" : "_" + expectedType.getSerializedName()));
        if (expectedType == net.minecraft.world.level.block.state.properties.ChestType.RIGHT) lastChestRightEmission = emission;
        else if (expectedType == net.minecraft.world.level.block.state.properties.ChestType.LEFT) lastChestLeftEmission = emission;
        else lastChestEmission = emission;
    }

    private record FrozenChestEmission(
        long frameIndex, BlockPos position, int lightCoords, float open, String chestType,
        String blockId, String materialIdentity
    ) {
        private String json() {
            return "{\"stage\":\"submit-model-returned\",\"frameIndex\":" + frameIndex
                + ",\"blockId\":\"" + blockId + "\",\"position\":{\"x\":" + position.getX()
                + ",\"y\":" + position.getY() + ",\"z\":" + position.getZ() + "}"
                + ",\"materialIdentity\":\"" + materialIdentity + "\",\"lightCoords\":" + lightCoords
                + ",\"facing\":\"south\",\"chestType\":\"" + chestType
                + "\",\"open\":" + format(open) + "}";
        }
    }

    /** Passive receipt after the ordinary Frozen purple Shulker Box model submission returns. */
    public static void observeShulkerBoxEmission(
        net.minecraft.client.renderer.blockentity.state.ShulkerBoxRenderState state
    ) {
        boolean openedEast = isOpenedEastShulkerScenario();
        boolean undyed = isDefaultShulkerScenario();
        Direction expectedFacing = openedEast ? Direction.EAST : Direction.UP;
        float expectedProgress = openedEast ? 1.0F : 0.0F;
        if (!ENABLED || complete || failed || !isShulkerScenario()
            || shulkerFixturePosition == null || !state.blockPos.equals(shulkerFixturePosition)
            || (undyed ? state.color != null : state.color != DyeColor.PURPLE)
            || state.direction != expectedFacing || state.progress != expectedProgress) return;
        ClientLevel level = Minecraft.getInstance().level;
        if (level == null || !level.getBlockState(shulkerFixturePosition).is(undyed ? Blocks.SHULKER_BOX : Blocks.PURPLE_SHULKER_BOX)
            || level.getBlockState(shulkerFixturePosition).getValue(net.minecraft.world.level.block.ShulkerBoxBlock.FACING) != expectedFacing
            || !(level.getBlockEntity(shulkerFixturePosition)
                instanceof net.minecraft.world.level.block.entity.ShulkerBoxBlockEntity shulker)
            || (undyed ? shulker.getColor() != null : shulker.getColor() != DyeColor.PURPLE)
            || shulker.getAnimationStatus() != (openedEast
                ? net.minecraft.world.level.block.entity.ShulkerBoxBlockEntity.AnimationStatus.OPENED
                : net.minecraft.world.level.block.entity.ShulkerBoxBlockEntity.AnimationStatus.CLOSED)) return;
        lastShulkerEmission = new FrozenShulkerEmission(
            renderedFrameIndex + 1, shulkerFixturePosition, state.lightCoords, state.direction, state.progress,
            shulker.getAnimationStatus(), undyed);
    }

