                + "\",\"position\":{\"x\":" + position.getX()
                + ",\"y\":" + position.getY() + ",\"z\":" + position.getZ() + "}"
                + ",\"materialIdentity\":\"" + (undyed ? "minecraft:entity/shulker/shulker" : "minecraft:entity/shulker/shulker_purple")
                + "\",\"lightCoords\":" + lightCoords
                + ",\"facing\":\"" + facing.getName() + "\",\"color\":\"" + (undyed ? "undyed" : "purple") + "\",\"status\":\""
                + status.name().toLowerCase(java.util.Locale.ROOT) + "\",\"progress\":" + format(progress) + "}";
