                + ",\"standing\":" + standing + ",\"rotation\":" + (standing ? 8 : -1)
                + ",\"facing\":\"" + facing + "\",\"angle\":" + format(angle)
                + ",\"baseColor\":\"" + baseColor + "\",\"patternCount\":" + (twoPatterns ? 2 : patterned ? 1 : 0)
                + ",\"patternLayers\":\"" + (twoPatterns ? "minecraft:cross:red,minecraft:border:blue"
                    : patterned ? "minecraft:cross:red" : "") + "\",\"phase\":" + format(phase) + "}";
