    /** Places an unpowered standing skeleton skull at a deterministic half-turn. */
    private static boolean setupSkullFixture(Minecraft minecraft, ClientLevel clientLevel, LocalPlayer player) {
        if (!isSkeletonSkullScenario()) return true;
        if (skullFixturePosition != null
            && hasExpectedSkullBlockState(clientLevel.getBlockState(skullFixturePosition))
            && clientLevel.getBlockState(skullFixturePosition)
                .getValue(net.minecraft.world.level.block.AbstractSkullBlock.POWERED) == isAnimatedSkullScenario()
            && clientLevel.getBlockEntity(skullFixturePosition)
                instanceof net.minecraft.world.level.block.entity.SkullBlockEntity skull
            && (isAnimatedSkullScenario() ? skull.getAnimation(0.0F) > 0.0F
                : skull.getAnimation(0.0F) == 0.0F)
            && (!isPlayerHeadScenario() || expectedPlayerHeadProfile().equals(skull.getOwnerProfile()))) {
            if (isBreakingSkullScenario()) {
                minecraft.levelRenderer.destroyBlockProgress(-0x534b554c, skullFixturePosition, MODEL_MESH_DESTROY_STAGE);
            }
            return true;
        }
        MinecraftServer server = minecraft.getSingleplayerServer();
        if (skullFixtureSpawnQueued || server == null) return false;
        Vec3 forward = player.getLookAngle();
        if (forward.lengthSqr() < 1.0e-4) forward = new Vec3(0.0, 0.0, 1.0);
        BlockPos position = BlockPos.containing(
            player.getEyePosition().add(forward.normalize().scale(4.0)).add(0.0, -1.25, 0.0));
        var dimension = clientLevel.dimension();
        skullFixturePosition = position;
        skullFixtureSpawnQueued = true;
        server.execute(() -> {
            ServerLevel serverLevel = server.getLevel(dimension);
            if (serverLevel == null) {
                skullFixtureSpawnQueued = false;
                return;
            }
            prepareEnchantingTableFixtureSite(serverLevel, position);
            if (isWallSkullScenario()) {
                serverLevel.setBlock(position.relative(expectedWallSkullFacing().getOpposite()),
                    Blocks.STONE.defaultBlockState(), 3);
            }
            BlockState state = isWallSkullScenario()
                ? expectedWallSkullBlock().defaultBlockState()
                    .setValue(net.minecraft.world.level.block.WallSkullBlock.FACING, expectedWallSkullFacing())
                : expectedStandingSkullBlock().defaultBlockState()
                    .setValue(net.minecraft.world.level.block.SkullBlock.ROTATION, 8);
            serverLevel.setBlock(position, state
                .setValue(net.minecraft.world.level.block.AbstractSkullBlock.POWERED, isAnimatedSkullScenario()), 3);
            if (isPlayerHeadScenario()
                && serverLevel.getBlockEntity(position) instanceof net.minecraft.world.level.block.entity.SkullBlockEntity skull) {
                var output = net.minecraft.world.level.storage.TagValueOutput.createWithContext(
                    net.minecraft.util.ProblemReporter.DISCARDING, serverLevel.registryAccess());
                output.store("profile", net.minecraft.world.item.component.ResolvableProfile.CODEC, expectedPlayerHeadProfile());
                skull.loadWithComponents(net.minecraft.world.level.storage.TagValueInput.create(
                    net.minecraft.util.ProblemReporter.DISCARDING, serverLevel.registryAccess(), output.buildResult()));
                skull.setChanged();
                serverLevel.sendBlockUpdated(position, state, state, 3);
            }
        });
        return false;
    }

    private static boolean setupStructureBlockFixture(Minecraft minecraft, ClientLevel clientLevel, LocalPlayer player) {
        boolean invisibleScenario = "structure-block-invisible-cells".equals(MODEL_MESH_SCENARIO);
        if (!("structure-block-box".equals(MODEL_MESH_SCENARIO) || invisibleScenario)) return true;
        if (structureBlockFixturePosition != null
            && clientLevel.getBlockState(structureBlockFixturePosition).is(Blocks.STRUCTURE_BLOCK)
            && clientLevel.getBlockState(structureBlockFixturePosition)
                .getValue(net.minecraft.world.level.block.StructureBlock.MODE)
                == net.minecraft.world.level.block.state.properties.StructureMode.SAVE
            && clientLevel.getBlockEntity(structureBlockFixturePosition)
                instanceof net.minecraft.world.level.block.entity.StructureBlockEntity structure
            && structure.getStructurePos().equals(new BlockPos(1, 1, 1))
            && structure.getStructureSize().equals(new net.minecraft.core.Vec3i(3, 2, 4))
            && structure.getShowAir() == invisibleScenario && structure.getShowBoundingBox()
            && (!invisibleScenario || structureFixtureCellsReady(clientLevel, structureBlockFixturePosition))) return true;
        MinecraftServer server = minecraft.getSingleplayerServer();
        if (structureBlockFixtureSpawnQueued || server == null) return false;
        Vec3 forward = player.getLookAngle();
        if (forward.lengthSqr() < 1.0e-4) forward = new Vec3(0.0, 0.0, 1.0);
        BlockPos position = BlockPos.containing(
            player.getEyePosition().add(forward.normalize().scale(4.0)).add(0.0, -1.25, 0.0));
        var dimension = clientLevel.dimension();
        structureBlockFixturePosition = position;
        structureBlockFixtureSpawnQueued = true;
        server.execute(() -> {
            ServerLevel serverLevel = server.getLevel(dimension);
            if (serverLevel == null) {
                structureBlockFixtureSpawnQueued = false;
                return;
            }
            prepareEnchantingTableFixtureSite(serverLevel, position);
            var state = Blocks.STRUCTURE_BLOCK.defaultBlockState().setValue(
                net.minecraft.world.level.block.StructureBlock.MODE,
                net.minecraft.world.level.block.state.properties.StructureMode.SAVE);
            serverLevel.setBlock(position, state, 3);
            if (serverLevel.getBlockEntity(position)
                instanceof net.minecraft.world.level.block.entity.StructureBlockEntity structure) {
                structure.setMode(net.minecraft.world.level.block.state.properties.StructureMode.SAVE);
                structure.setStructurePos(new BlockPos(1, 1, 1));
                structure.setStructureSize(new net.minecraft.core.Vec3i(3, 2, 4));
                structure.setShowAir(invisibleScenario);
                structure.setShowBoundingBox(true);
                structure.setChanged();
                serverLevel.sendBlockUpdated(position, state, state, 3);
                if (invisibleScenario) {
                    BlockPos origin = position.offset(1, 1, 1);
                    for (int x = 0; x < 3; x++) for (int y = 0; y < 2; y++) for (int z = 0; z < 4; z++)
                        serverLevel.setBlock(origin.offset(x, y, z), Blocks.STONE.defaultBlockState(), 3);
                    serverLevel.setBlock(origin, Blocks.AIR.defaultBlockState(), 3);
                    serverLevel.setBlock(origin.offset(1, 0, 0), Blocks.STRUCTURE_VOID.defaultBlockState(), 3);
                    serverLevel.setBlock(origin.offset(2, 0, 0), Blocks.BARRIER.defaultBlockState(), 3);
                    serverLevel.setBlock(origin.offset(0, 1, 0), Blocks.LIGHT.defaultBlockState(), 3);
                }
            }
        });
        return false;
    }

    private static boolean structureFixtureCellsReady(net.minecraft.world.level.Level level, BlockPos position) {
        BlockPos origin = position.offset(1, 1, 1);
        for (int x = 0; x < 3; x++) for (int y = 0; y < 2; y++) for (int z = 0; z < 4; z++) {
            var state = level.getBlockState(origin.offset(x, y, z));
            if (x == 0 && y == 0 && z == 0 ? !state.isAir()
                : x == 1 && y == 0 && z == 0 ? !state.is(Blocks.STRUCTURE_VOID)
                : x == 2 && y == 0 && z == 0 ? !state.is(Blocks.BARRIER)
                : x == 0 && y == 1 && z == 0 ? !state.is(Blocks.LIGHT)
                : !state.is(Blocks.STONE)) return false;
        }
        return true;
    }

    private static boolean setupTestInstanceFixture(Minecraft minecraft, ClientLevel clientLevel, LocalPlayer player) {
        boolean successful = "test-instance-success".equals(MODEL_MESH_SCENARIO);
        boolean cleared = "test-instance-cleared".equals(MODEL_MESH_SCENARIO);
        boolean requiredFailed = "test-instance-required-failed".equals(MODEL_MESH_SCENARIO);
        boolean optionalFailed = "test-instance-optional-failed".equals(MODEL_MESH_SCENARIO);
        if (!("test-instance-composition".equals(MODEL_MESH_SCENARIO) || successful || cleared || requiredFailed || optionalFailed)) return true;
        if (testInstanceFixturePosition != null
            && clientLevel.getBlockState(testInstanceFixturePosition).is(Blocks.TEST_INSTANCE_BLOCK)
            && clientLevel.getBlockEntity(testInstanceFixturePosition)
                instanceof net.minecraft.world.level.block.entity.TestInstanceBlockEntity testInstance
            && testInstance.getSize().equals(new net.minecraft.core.Vec3i(3, 2, 4))
            && testInstance.getRotation() == net.minecraft.world.level.block.Rotation.NONE
            && (!optionalFailed || testInstance.test().map(key -> key.location().toString()
                .equals("mattmc_model_fixture:optional_failure")).orElse(false))
            && (cleared ? testInstance.getBeamSections().isEmpty()
                : testInstance.getBeamSections().size() == 1
					&& testInstance.getBeamSections().get(0).getColor() == (optionalFailed ? 0xffff8000 : requiredFailed ? 0xffff0000 : successful ? 0xff00ff00 : 0xff808080))
            && (successful || cleared ? testInstance.getErrorMarkers().isEmpty() && testInstance.errorMessage().isEmpty()
                : testInstance.getErrorMarkers().size() == 1
                    && testInstance.getErrorMarkers().get(0).pos().equals(testInstanceFixturePosition.offset(2, 1, 2))
                    && "Expected failure".equals(testInstance.getErrorMarkers().get(0).text().getString())
                    && (requiredFailed || optionalFailed ? testInstance.errorMessage().isPresent()
                        && (optionalFailed ? "Optional failure" : "Required failure").equals(testInstance.errorMessage().get().getString())
                        : testInstance.errorMessage().isEmpty()))) return true;
        MinecraftServer server = minecraft.getSingleplayerServer();
        if (testInstanceFixtureSpawnQueued || server == null) return false;
        Vec3 forward = player.getLookAngle();
        if (forward.lengthSqr() < 1.0e-4) forward = new Vec3(0.0, 0.0, 1.0);
        BlockPos position = BlockPos.containing(
            player.getEyePosition().add(forward.normalize().scale(4.0)).add(0.0, -1.25, 0.0));
        var dimension = clientLevel.dimension();
        testInstanceFixturePosition = position;
        testInstanceFixtureSpawnQueued = true;
        server.execute(() -> {
            ServerLevel serverLevel = server.getLevel(dimension);
            if (serverLevel == null) {
                testInstanceFixtureSpawnQueued = false;
                return;
            }
            prepareEnchantingTableFixtureSite(serverLevel, position);
            var state = Blocks.TEST_INSTANCE_BLOCK.defaultBlockState();
            serverLevel.setBlock(position, state, 3);
            if (serverLevel.getBlockEntity(position)
                instanceof net.minecraft.world.level.block.entity.TestInstanceBlockEntity testInstance) {
                var testKey = net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.TEST_INSTANCE,
                    net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("mattmc_model_fixture", "optional_failure"));
                testInstance.set(new net.minecraft.world.level.block.entity.TestInstanceBlockEntity.Data(
                    optionalFailed ? java.util.Optional.of(testKey) : java.util.Optional.empty(), new net.minecraft.core.Vec3i(3, 2, 4),
                    net.minecraft.world.level.block.Rotation.NONE, false,
					cleared ? net.minecraft.world.level.block.entity.TestInstanceBlockEntity.Status.CLEARED
					: successful || requiredFailed || optionalFailed ? net.minecraft.world.level.block.entity.TestInstanceBlockEntity.Status.FINISHED
                        : net.minecraft.world.level.block.entity.TestInstanceBlockEntity.Status.RUNNING,
					requiredFailed || optionalFailed ? java.util.Optional.of(net.minecraft.network.chat.Component.literal(
						optionalFailed ? "Optional failure" : "Required failure")) : java.util.Optional.empty()));
                if (!successful && !cleared) testInstance.markError(position.offset(2, 1, 2),
                    net.minecraft.network.chat.Component.literal("Expected failure"));
                testInstance.setChanged();
                serverLevel.sendBlockUpdated(position, state, state, 3);
            }
        });
        return false;
    }

    private static void prepareActiveConduitFixture(ServerLevel level, BlockPos position) {
        for (int x = -1; x <= 1; x++) {
            for (int y = -1; y <= 1; y++) {
                for (int z = -1; z <= 1; z++) {
                    BlockPos waterPosition = position.offset(x, y, z);
                    if (!waterPosition.equals(position)) {
                        level.setBlock(waterPosition, Blocks.WATER.defaultBlockState(), 3);
                    }
                }
            }
        }
        int requiredFrameBlocks = isHuntingConduitModelScenario() ? 42 : 16;
        int frameBlocks = 0;
        for (int x = -2; x <= 2 && frameBlocks < requiredFrameBlocks; x++) {
            for (int y = -2; y <= 2 && frameBlocks < requiredFrameBlocks; y++) {
                for (int z = -2; z <= 2 && frameBlocks < requiredFrameBlocks; z++) {
                    int ax = Math.abs(x);
                    int ay = Math.abs(y);
                    int az = Math.abs(z);
                    if ((ax > 1 || ay > 1 || az > 1)
                        && (x == 0 && (ay == 2 || az == 2)
                            || y == 0 && (ax == 2 || az == 2)
                            || z == 0 && (ax == 2 || ay == 2))) {
                        level.setBlock(position.offset(x, y, z), Blocks.PRISMARINE.defaultBlockState(), 3);
                        frameBlocks++;
                    }
                }
            }
        }
    }

