    /** Places the same dust-stage-three south-exposed suspicious-sand item producer used by Current. */
    private static boolean setupBrushableItemFixture(Minecraft minecraft, ClientLevel clientLevel, LocalPlayer player) {
        if (!"brushable-block".equals(MODEL_MESH_SCENARIO)) return true;
        if (brushableItemFixturePosition != null
            && clientLevel.getBlockState(brushableItemFixturePosition).is(Blocks.SUSPICIOUS_SAND)
            && clientLevel.getBlockState(brushableItemFixturePosition)
                .getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.DUSTED) == 3
            && clientLevel.getBlockEntity(brushableItemFixturePosition)
                instanceof net.minecraft.world.level.block.entity.BrushableBlockEntity brushable
            && brushable.getItem().is(Items.BEEF) && brushable.getHitDirection() == Direction.SOUTH) return true;
        MinecraftServer server = minecraft.getSingleplayerServer();
        if (brushableItemFixtureSpawnQueued || server == null) return false;
        Vec3 forward = player.getLookAngle();
        if (forward.lengthSqr() < 1.0e-4) forward = new Vec3(0.0, 0.0, 1.0);
        BlockPos position = BlockPos.containing(
            player.getEyePosition().add(forward.normalize().scale(4.0)).add(0.0, -1.25, 0.0));
        var dimension = clientLevel.dimension();
        brushableItemFixturePosition = position;
        brushableItemFixtureSpawnQueued = true;
        server.execute(() -> {
            ServerLevel serverLevel = server.getLevel(dimension);
            if (serverLevel == null) {
                brushableItemFixtureSpawnQueued = false;
                return;
            }
            prepareEnchantingTableFixtureSite(serverLevel, position);
            var state = Blocks.SUSPICIOUS_SAND.defaultBlockState()
                .setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.DUSTED, 3);
            serverLevel.setBlock(position, state, 3);
            if (serverLevel.getBlockEntity(position)
                instanceof net.minecraft.world.level.block.entity.BrushableBlockEntity brushable) {
                var output = net.minecraft.world.level.storage.TagValueOutput.createWithContext(
                    net.minecraft.util.ProblemReporter.DISCARDING, serverLevel.registryAccess());
                output.store("item", ItemStack.CODEC, new ItemStack(Items.BEEF));
                output.store("hit_direction", Direction.LEGACY_ID_CODEC, Direction.SOUTH);
                brushable.loadWithComponents(net.minecraft.world.level.storage.TagValueInput.create(
                    net.minecraft.util.ProblemReporter.DISCARDING, serverLevel.registryAccess(), output.buildResult()));
                brushable.setChanged();
                serverLevel.sendBlockUpdated(position, state, state, 3);
            }
        });
        return false;
    }

    /** Places the same stable ordinary unlocking-vault display-item producer used by Current. */
    private static boolean setupVaultItemFixture(Minecraft minecraft, ClientLevel clientLevel, LocalPlayer player) {
        if (!"vault-unlocking".equals(MODEL_MESH_SCENARIO)) return true;
        if (vaultItemFixturePosition != null
            && clientLevel.getBlockState(vaultItemFixturePosition).is(Blocks.VAULT)
            && clientLevel.getBlockState(vaultItemFixturePosition)
                .getValue(net.minecraft.world.level.block.VaultBlock.FACING) == Direction.SOUTH
            && clientLevel.getBlockState(vaultItemFixturePosition)
                .getValue(net.minecraft.world.level.block.VaultBlock.STATE)
                == net.minecraft.world.level.block.entity.vault.VaultState.UNLOCKING
            && !clientLevel.getBlockState(vaultItemFixturePosition)
                .getValue(net.minecraft.world.level.block.VaultBlock.OMINOUS)
            && clientLevel.getBlockEntity(vaultItemFixturePosition)
                instanceof net.minecraft.world.level.block.entity.vault.VaultBlockEntity vault
            && vault.getSharedData().getDisplayItem().is(Items.BEEF)) return true;
        MinecraftServer server = minecraft.getSingleplayerServer();
        if (vaultItemFixtureSpawnQueued || server == null) return false;
        Vec3 forward = player.getLookAngle();
        if (forward.lengthSqr() < 1.0e-4) forward = new Vec3(0.0, 0.0, 1.0);
        BlockPos position = BlockPos.containing(
            player.getEyePosition().add(forward.normalize().scale(4.0)).add(0.0, -1.25, 0.0));
        var dimension = clientLevel.dimension();
        vaultItemFixturePosition = position;
        vaultItemFixtureSpawnQueued = true;
        server.execute(() -> {
            ServerLevel serverLevel = server.getLevel(dimension);
            if (serverLevel == null) {
                vaultItemFixtureSpawnQueued = false;
                return;
            }
            prepareEnchantingTableFixtureSite(serverLevel, position);
            var state = Blocks.VAULT.defaultBlockState()
                .setValue(net.minecraft.world.level.block.VaultBlock.FACING, Direction.SOUTH)
                .setValue(net.minecraft.world.level.block.VaultBlock.STATE,
                    net.minecraft.world.level.block.entity.vault.VaultState.UNLOCKING)
                .setValue(net.minecraft.world.level.block.VaultBlock.OMINOUS, false);
            serverLevel.setBlock(position, state, 3);
            if (serverLevel.getBlockEntity(position)
                instanceof net.minecraft.world.level.block.entity.vault.VaultBlockEntity vault) {
                var serverData = new net.minecraft.nbt.CompoundTag();
                serverData.putLong("state_updating_resumes_at", Long.MAX_VALUE);
                var tag = new net.minecraft.nbt.CompoundTag();
                tag.put("server_data", serverData);
                vault.loadWithComponents(net.minecraft.world.level.storage.TagValueInput.create(
                    net.minecraft.util.ProblemReporter.DISCARDING, serverLevel.registryAccess(), tag));
                vault.getSharedData().setDisplayItem(new ItemStack(Items.BEEF));
                vault.setChanged();
                serverLevel.sendBlockUpdated(position, state, state, 3);
            }
        });
        return false;
    }

