    private static boolean isTrialSpawnerScenario() {
        return "trial-spawner".equals(MODEL_MESH_SCENARIO)
            || "trial-spawner-ominous".equals(MODEL_MESH_SCENARIO)
            || "trial-spawner-active".equals(MODEL_MESH_SCENARIO);
    }

    private static boolean expectedTrialSpawnerOminous() {
        return "trial-spawner-ominous".equals(MODEL_MESH_SCENARIO);
    }

    private static net.minecraft.world.level.block.entity.trialspawner.TrialSpawnerState expectedTrialSpawnerState() {
        return "trial-spawner-active".equals(MODEL_MESH_SCENARIO)
            ? net.minecraft.world.level.block.entity.trialspawner.TrialSpawnerState.ACTIVE
            : net.minecraft.world.level.block.entity.trialspawner.TrialSpawnerState.WAITING_FOR_PLAYERS;
    }

    private static void stabilizeActiveTrialSpawner(
        net.minecraft.world.level.block.entity.TrialSpawnerBlockEntity spawner, UUID playerId
    ) {
        var data = spawner.getTrialSpawner().getStateData();
        var packed = data.pack();
        data.apply(new net.minecraft.world.level.block.entity.trialspawner.TrialSpawnerStateData.Packed(
            Set.of(playerId), Set.of(), packed.cooldownEndsAt(), Long.MAX_VALUE, 0,
            packed.nextSpawnData(), packed.ejectingLootTable()));
    }

    /** Places a waiting trial spawner with the scenario's normal or ominous configuration and a nested pig. */
    private static boolean setupTrialSpawnerEntityFixture(Minecraft minecraft, ClientLevel clientLevel, LocalPlayer player) {
        if (!isTrialSpawnerScenario()) return true;
        if (trialSpawnerEntityFixturePosition != null
            && clientLevel.getBlockState(trialSpawnerEntityFixturePosition).is(Blocks.TRIAL_SPAWNER)
            && clientLevel.getBlockState(trialSpawnerEntityFixturePosition)
                .getValue(net.minecraft.world.level.block.TrialSpawnerBlock.OMINOUS) == expectedTrialSpawnerOminous()
            && clientLevel.getBlockState(trialSpawnerEntityFixturePosition)
                .getValue(net.minecraft.world.level.block.TrialSpawnerBlock.STATE)
                == expectedTrialSpawnerState()
            && clientLevel.getBlockEntity(trialSpawnerEntityFixturePosition)
                instanceof net.minecraft.world.level.block.entity.TrialSpawnerBlockEntity spawner
            && spawner.getTrialSpawner().getStateData().getOrCreateDisplayEntity(
                spawner.getTrialSpawner(), clientLevel,
                expectedTrialSpawnerState())
                instanceof net.minecraft.world.entity.animal.Pig) return true;
        MinecraftServer server = minecraft.getSingleplayerServer();
        if (trialSpawnerEntityFixtureSpawnQueued || server == null) return false;
        Vec3 forward = player.getLookAngle();
        if (forward.lengthSqr() < 1.0e-4) forward = new Vec3(0.0, 0.0, 1.0);
        BlockPos position = BlockPos.containing(
            player.getEyePosition().add(forward.normalize().scale(4.0)).add(0.0, -1.25, 0.0));
        var dimension = clientLevel.dimension();
        trialSpawnerEntityFixturePosition = position;
        trialSpawnerEntityFixtureSpawnQueued = true;
        server.execute(() -> {
            ServerLevel serverLevel = server.getLevel(dimension);
            if (serverLevel == null) {
                trialSpawnerEntityFixtureSpawnQueued = false;
                return;
            }
            prepareEnchantingTableFixtureSite(serverLevel, position);
            var state = Blocks.TRIAL_SPAWNER.defaultBlockState()
                .setValue(net.minecraft.world.level.block.TrialSpawnerBlock.STATE,
                    expectedTrialSpawnerState())
                .setValue(net.minecraft.world.level.block.TrialSpawnerBlock.OMINOUS, expectedTrialSpawnerOminous());
            serverLevel.setBlock(position, state, 3);
            if (serverLevel.getBlockEntity(position)
                instanceof net.minecraft.world.level.block.entity.TrialSpawnerBlockEntity spawner) {
                spawner.setEntityId(EntityType.PIG, serverLevel.getRandom());
                spawner.getTrialSpawner().setPlayerDetector((level, selector, blockPos, range, lineOfSight) -> List.of());
                spawner.setState(serverLevel, expectedTrialSpawnerState());
                if (expectedTrialSpawnerOminous()) {
                    spawner.getTrialSpawner().applyOminous(serverLevel, position);
                }
                if (expectedTrialSpawnerState()
                    == net.minecraft.world.level.block.entity.trialspawner.TrialSpawnerState.ACTIVE) {
                    stabilizeActiveTrialSpawner(spawner, player.getUUID());
                }
                var finalState = serverLevel.getBlockState(position);
                serverLevel.sendBlockUpdated(position, finalState, finalState, 3);
            }
        });
        return false;
    }

    /** Places the same ordinary procedural end-portal block entity used by Current. */
    private static boolean setupEndPortalFixture(Minecraft minecraft, ClientLevel clientLevel, LocalPlayer player) {
        if (!"end-portal".equals(MODEL_MESH_SCENARIO)) return true;
        if (endPortalFixturePosition != null
            && clientLevel.getBlockState(endPortalFixturePosition).is(Blocks.END_PORTAL)
            && clientLevel.getBlockEntity(endPortalFixturePosition)
                instanceof net.minecraft.world.level.block.entity.TheEndPortalBlockEntity) return true;
        MinecraftServer server = minecraft.getSingleplayerServer();
        if (endPortalFixtureSpawnQueued || server == null) return false;
        Vec3 forward = player.getLookAngle();
        if (forward.lengthSqr() < 1.0e-4) forward = new Vec3(0.0, 0.0, 1.0);
        BlockPos position = BlockPos.containing(
            player.getEyePosition().add(forward.normalize().scale(4.0)).add(0.0, -1.25, 0.0));
        var dimension = clientLevel.dimension();
        endPortalFixturePosition = position;
        endPortalFixtureSpawnQueued = true;
        server.execute(() -> {
            ServerLevel serverLevel = server.getLevel(dimension);
            if (serverLevel == null) {
                endPortalFixtureSpawnQueued = false;
                return;
            }
            prepareEnchantingTableFixtureSite(serverLevel, position);
            serverLevel.setBlock(position, Blocks.END_PORTAL.defaultBlockState(), 3);
        });
        return false;
    }

    /** Places and stabilizes an ordinary cooling-down End Gateway producer. */
    private static boolean setupEndGatewayFixture(Minecraft minecraft, ClientLevel clientLevel, LocalPlayer player) {
        if (!"end-gateway".equals(MODEL_MESH_SCENARIO)) return true;
        if (endGatewayFixturePosition != null
            && clientLevel.getBlockState(endGatewayFixturePosition).is(Blocks.END_GATEWAY)
            && clientLevel.getBlockEntity(endGatewayFixturePosition)
                instanceof net.minecraft.world.level.block.entity.TheEndGatewayBlockEntity gateway) {
            stabilizeEndGatewayFixture(clientLevel, endGatewayFixturePosition, gateway);
            return true;
        }
        MinecraftServer server = minecraft.getSingleplayerServer();
        if (endGatewayFixtureSpawnQueued || server == null) return false;
        Vec3 forward = player.getLookAngle();
        if (forward.lengthSqr() < 1.0e-4) forward = new Vec3(0.0, 0.0, 1.0);
        BlockPos position = BlockPos.containing(
            player.getEyePosition().add(forward.normalize().scale(4.0)).add(0.0, -1.25, 0.0));
        var dimension = clientLevel.dimension();
        endGatewayFixturePosition = position;
        endGatewayFixtureSpawnQueued = true;
        server.execute(() -> {
            ServerLevel serverLevel = server.getLevel(dimension);
            if (serverLevel == null) {
                endGatewayFixtureSpawnQueued = false;
                return;
            }
            prepareEnchantingTableFixtureSite(serverLevel, position);
            var state = Blocks.END_GATEWAY.defaultBlockState();
            serverLevel.setBlock(position, state, 3);
            if (serverLevel.getBlockEntity(position)
                instanceof net.minecraft.world.level.block.entity.TheEndGatewayBlockEntity gateway) {
                stabilizeEndGatewayFixture(serverLevel, position, gateway);
                gateway.setChanged();
                serverLevel.sendBlockUpdated(position, state, state, 3);
            }
        });
        return false;
    }

    private static void stabilizeEndGatewayFixture(
        net.minecraft.world.level.Level level, BlockPos position,
        net.minecraft.world.level.block.entity.TheEndGatewayBlockEntity gateway
    ) {
        while (gateway.isSpawning()) {
            net.minecraft.world.level.block.entity.TheEndGatewayBlockEntity.beamAnimationTick(
                level, position, Blocks.END_GATEWAY.defaultBlockState(), gateway);
        }
        gateway.triggerEvent(1, 0);
        for (int tick = 0; tick < 20; tick++) {
            net.minecraft.world.level.block.entity.TheEndGatewayBlockEntity.beamAnimationTick(
                level, position, Blocks.END_GATEWAY.defaultBlockState(), gateway);
        }
    }

