    private static String enchantingTableBookFixtureJson(Minecraft minecraft, String scenario) {
        boolean requested = scenario.equals(MODEL_MESH_SCENARIO);
        String blockId = "lectern".equals(scenario) ? "minecraft:lectern" : "minecraft:enchanting_table";
        boolean present = requested && enchantingTableFixturePosition != null && minecraft.level != null
            && ("lectern".equals(scenario)
                ? minecraft.level.getBlockState(enchantingTableFixturePosition).is(Blocks.LECTERN)
                    && minecraft.level.getBlockState(enchantingTableFixturePosition)
                        .getValue(net.minecraft.world.level.block.LecternBlock.HAS_BOOK)
                : minecraft.level.getBlockState(enchantingTableFixturePosition).is(Blocks.ENCHANTING_TABLE))
            && minecraft.level.getBlockEntity(enchantingTableFixturePosition) != null;
        return "{\"requested\":" + requested + ",\"present\":" + present
            + ",\"blockId\":\"" + blockId + "\",\"position\":"
            + (enchantingTableFixturePosition == null ? "null" : "{\"x\":" + enchantingTableFixturePosition.getX()
                + ",\"y\":" + enchantingTableFixturePosition.getY() + ",\"z\":" + enchantingTableFixturePosition.getZ() + "}")
            + ",\"emission\":" + (lastEnchantingTableBookEmission == null ? "null" : lastEnchantingTableBookEmission.json()) + "}";
    }

