    private static String oakHangingSignFixtureJson(Minecraft minecraft) {
        boolean requested = isOakHangingSignScenario();
        var sign = oakHangingSignFixturePosition != null && minecraft.level != null
            && minecraft.level.getBlockEntity(oakHangingSignFixturePosition)
                instanceof net.minecraft.world.level.block.entity.HangingSignBlockEntity value ? value : null;
        BlockState state = oakHangingSignFixturePosition != null && minecraft.level != null
            ? minecraft.level.getBlockState(oakHangingSignFixturePosition) : null;
        boolean wall = isWallOakHangingSignScenario();
        boolean present = requested && state != null && (wall
            ? state.is(Blocks.OAK_WALL_HANGING_SIGN)
                && state.getValue(net.minecraft.world.level.block.WallHangingSignBlock.FACING) == Direction.NORTH
                && minecraft.level.getBlockState(oakHangingSignFixturePosition.east()).is(Blocks.STONE)
            : state.is(Blocks.OAK_HANGING_SIGN)
                && state.getValue(net.minecraft.world.level.block.CeilingHangingSignBlock.ROTATION) == 8
                && state.getValue(net.minecraft.world.level.block.CeilingHangingSignBlock.ATTACHED)
                    == isAttachedOakHangingSignScenario()
                && minecraft.level.getBlockState(oakHangingSignFixturePosition.above()).is(Blocks.STONE))
            && sign != null && "Rust Vulkan".equals(sign.getFrontText().getMessage(0, false).getString())
            && "Frozen parity".equals(sign.getFrontText().getMessage(1, false).getString());
        return "{\"requested\":" + requested + ",\"present\":" + present
            + ",\"blockId\":\"minecraft:" + (wall ? "oak_wall_hanging_sign" : "oak_hanging_sign") + "\""
            + ",\"attachment\":\"" + (wall ? "wall" : isAttachedOakHangingSignScenario() ? "ceiling_middle" : "ceiling") + "\""
            + ",\"rotation\":" + (wall ? -1 : 8) + ",\"attached\":" + (!wall && isAttachedOakHangingSignScenario())
            + ",\"facing\":\"" + (wall ? "north" : "not-applicable") + "\""
            + ",\"frontLines\":[\"Rust Vulkan\",\"Frozen parity\"],\"position\":"
            + positionJson(oakHangingSignFixturePosition) + ",\"emission\":"
            + (lastOakHangingSignEmission == null ? "null" : lastOakHangingSignEmission.json()) + "}";
    }

