    private static String structureBlockFixtureJson(Minecraft minecraft) {
        boolean invisibleScenario = "structure-block-invisible-cells".equals(MODEL_MESH_SCENARIO);
        boolean requested = "structure-block-box".equals(MODEL_MESH_SCENARIO) || invisibleScenario;
        var structure = structureBlockFixturePosition != null && minecraft.level != null
            && minecraft.level.getBlockEntity(structureBlockFixturePosition)
                instanceof net.minecraft.world.level.block.entity.StructureBlockEntity value ? value : null;
        boolean present = requested && structureBlockFixturePosition != null && minecraft.level != null
            && minecraft.level.getBlockState(structureBlockFixturePosition).is(Blocks.STRUCTURE_BLOCK)
            && structure != null && structure.getMode() == net.minecraft.world.level.block.state.properties.StructureMode.SAVE
            && structure.getStructurePos().equals(new BlockPos(1, 1, 1))
            && structure.getStructureSize().equals(new net.minecraft.core.Vec3i(3, 2, 4))
            && structure.getShowAir() == invisibleScenario && structure.getShowBoundingBox()
            && (!invisibleScenario || structureFixtureCellsReady(minecraft.level, structureBlockFixturePosition));
        return "{\"requested\":" + requested + ",\"present\":" + present
            + ",\"blockId\":\"minecraft:structure_block\",\"structureMode\":\"save\""
            + ",\"showAir\":" + invisibleScenario + ",\"showBoundingBox\":true,\"localPos\":{\"x\":1,\"y\":1,\"z\":1}"
            + ",\"cellTypes\":[\"air\",\"structure_void\",\"barrier\",\"light\"]"
            + ",\"size\":{\"x\":3,\"y\":2,\"z\":4},\"position\":" + positionJson(structureBlockFixturePosition)
            + ",\"emission\":" + (lastStructureBlockBoxEmission == null ? "null" : lastStructureBlockBoxEmission.json()) + "}";
    }

    private static String testInstanceFixtureJson(Minecraft minecraft) {
        boolean successful = "test-instance-success".equals(MODEL_MESH_SCENARIO);
        boolean cleared = "test-instance-cleared".equals(MODEL_MESH_SCENARIO);
        boolean requiredFailed = "test-instance-required-failed".equals(MODEL_MESH_SCENARIO);
        boolean optionalFailed = "test-instance-optional-failed".equals(MODEL_MESH_SCENARIO);
        boolean requested = "test-instance-composition".equals(MODEL_MESH_SCENARIO) || successful || cleared || requiredFailed || optionalFailed;
        boolean present = requested && testInstanceFixturePosition != null && minecraft.level != null
            && minecraft.level.getBlockState(testInstanceFixturePosition).is(Blocks.TEST_INSTANCE_BLOCK)
            && minecraft.level.getBlockEntity(testInstanceFixturePosition)
                instanceof net.minecraft.world.level.block.entity.TestInstanceBlockEntity testInstance
            && testInstance.getSize().equals(new net.minecraft.core.Vec3i(3, 2, 4))
            && testInstance.getRotation() == net.minecraft.world.level.block.Rotation.NONE
            && (!optionalFailed || testInstance.test().map(key -> key.location().toString()
                .equals("mattmc_model_fixture:optional_failure")).orElse(false))
            && (cleared ? testInstance.getBeamSections().isEmpty()
                : testInstance.getBeamSections().size() == 1
                    && testInstance.getBeamSections().get(0).getColor() == (optionalFailed ? 0xffff8000 : requiredFailed ? 0xffff0000 : successful ? 0xff00ff00 : 0xff808080))
            && (successful || cleared ? testInstance.getErrorMarkers().isEmpty() && testInstance.errorMessage().isEmpty()
                : testInstance.getErrorMarkers().size() == 1
                    && (requiredFailed || optionalFailed ? testInstance.errorMessage().isPresent()
                        && (optionalFailed ? "Optional failure" : "Required failure").equals(testInstance.errorMessage().get().getString())
                        : testInstance.errorMessage().isEmpty()));
        return "{\"requested\":" + requested + ",\"present\":" + present
            + ",\"blockId\":\"minecraft:test_instance_block\",\"status\":\"" + (optionalFailed ? "finished_optional_failed" : requiredFailed ? "finished_required_failed" : cleared ? "cleared" : successful ? "finished_success" : "running") + "\""
            + ",\"localPos\":{\"x\":0,\"y\":1,\"z\":1},\"size\":{\"x\":3,\"y\":2,\"z\":4}"
            + ",\"errorLocalPos\":" + (successful || cleared ? "null" : "{\"x\":2,\"y\":1,\"z\":2}")
            + ",\"errorText\":\"" + (successful || cleared ? "" : "Expected failure") + "\""
            + ",\"failureMessage\":\"" + (optionalFailed ? "Optional failure" : requiredFailed ? "Required failure" : "") + "\""
            + ",\"position\":" + positionJson(testInstanceFixturePosition)
            + ",\"emission\":" + (lastTestInstanceCompositionEmission == null ? "null" : lastTestInstanceCompositionEmission.json()) + "}";
    }

